screen.template:
function {{id}}() {
  // Monta a tela {{label}}
  console.log('Tela {{id}} ativa');
  {{nextCall}}
}

input.template:
function {{id}}() {
  // Retorna o valor atual do campo {{label}}
  return read('{{id}}', 'value');
}

button.template:
function {{id}}() {
  // Disparado ao clicar no botão {{label}}
  {{targetCall}}
}

api.template:
async function {{id}}(body) {
  const response = await fetch('{{url}}', {
    method: '{{method}}',
    headers: { 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined
  });
  const data = await response.json();
  {{successBranch}}
}

navigate.template:
function {{id}}() {
  // Navega para a tela de destino
  navigateTo('{{target}}');
}
